	tlsFiles := natscell.TLSFiles{CAFile: path("ca.pem"), CertFile: path("cert.pem"), KeyFile: path("key.pem")}
	config := natscell.Config{Cell: "gru", Instance: "broker-a", Replicas: 1,
		CredentialsFile: path("controller.creds"), TLS: tlsFiles,
		Embedded: &natscell.Embedded{TLS: tlsFiles, RouteTLS: tlsFiles,
			OperatorJWTFile: path("operator.jwt"), SystemJWTFile: path("system.jwt"),
			CellJWTFile: path("cell.jwt"), SystemCredentialsFile: path("system.creds"),
			TicketPublicKeyFile: path("ticket.pub")},
	}
	expected := map[string]string{}
	for _, name := range []string{"ca.pem", "cert.pem", "key.pem", "controller.creds", "operator.jwt", "system.jwt", "cell.jwt", "system.creds", "ticket.pub", "response.key", "ticket.key", "host-nats-issuer.seed", "host-tls-issuer-key.pem", "host-tls-issuer-cert.pem"} {
		content := []byte("signed fixture " + name)
		expected[name] = digest(content)
		if err := os.WriteFile(path(name), content, 0o600); err != nil {
			t.Fatal(err)
		}
	}
	return LiveCredentials{Config: config, ServiceUID: uint32(os.Getuid()), ServiceGID: uint32(os.Getgid()),
		ResponseKeyFile: path("response.key"), BrokerTicketKeyFile: path("ticket.key"),
		HostNATSIssuerSeedFile: path("host-nats-issuer.seed"), HostTLSIssuerKeyFile: path("host-tls-issuer-key.pem"),
		HostTLSIssuerCertFile:  path("host-tls-issuer-cert.pem"),
		ValidateControllerKeys: func() error { return nil }, directory: directory, allowUnsafeAncestors: true}, expected
}

func (check LiveCredentials) verifyInventory(expected MaterialPins) error {
	dir, err := openMaterialDirectory(check.directory, check.ServiceUID, check.ServiceGID, 0o700, check.allowUnsafeAncestors)
	if err != nil {
		return fmt.Errorf("%w: open fixed credential directory: %v", ErrLiveCredentials, err)
	}
	defer unix.Close(dir)
	copyFD, err := unix.Dup(dir)
	if err != nil {
		return err
	}
	file := os.NewFile(uintptr(copyFD), check.directory)
	entries, err := file.ReadDir(-1)
	_ = file.Close()
	if err != nil || len(entries) != expected.size() {
		return fmt.Errorf("%w: installed credential inventory differs", ErrLiveCredentials)
	}
	for _, entry := range entries {
		if !expected.known(entry.Name()) {
			return fmt.Errorf("%w: unpinned credential file", ErrLiveCredentials)
		}
		var content []byte
		var err error
		if want := expected.Digests[entry.Name()]; want != "" {
			content, err = readMaterial(dir, entry.Name(), check.ServiceUID, check.ServiceGID, want, bootstrap.MaxSecretBytes)
		} else {
			// Issued files were checked by rule in VerifyRestart.
			content, err = readUnpinned(dir, entry.Name(), check.ServiceUID, check.ServiceGID, bootstrap.MaxSecretBytes)
		}
		if err != nil {
			return fmt.Errorf("%w: installed credential %s: %v", ErrLiveCredentials, entry.Name(), err)
		}
		clear(content)
	}
	return nil
}

func readMaterial(dir int, name string, uid, gid uint32, want string, maximum int64) ([]byte, error) {
	if !markerNameRE.MatchString(name) || !markerDigestRE.MatchString(want) || maximum <= 0 || maximum > bootstrap.MaxSecretBytes {
		return nil, ErrMaterial
	}
	fd, err := unix.Openat(dir, name, unix.O_RDONLY|unix.O_CLOEXEC|unix.O_NOFOLLOW|unix.O_NONBLOCK, 0)
	if err != nil {
		return nil, err
	}
	file := os.NewFile(uintptr(fd), name)
	defer file.Close()
	var stat unix.Stat_t
	if err := unix.Fstat(fd, &stat); err != nil || stat.Mode&unix.S_IFMT != unix.S_IFREG ||
		stat.Uid != uid || stat.Gid != gid || stat.Mode&0o777 != 0o600 || stat.Nlink != 1 ||
		stat.Size <= 0 || stat.Size > maximum {
		return nil, ErrMaterial
	}
	content, err := io.ReadAll(io.LimitReader(file, maximum+1))
	if err != nil || len(content) == 0 || int64(len(content)) > maximum || digest(content) != want {
		clear(content)
		return nil, ErrMaterial
	}
	return content, nil
}

func openMaterialDirectory(path string, uid, gid uint32, mode uint32, allowUnsafeAncestors bool) (int, error) {
	if !filepath.IsAbs(path) || filepath.Clean(path) != path {
		return -1, ErrMaterial
	}
	fd, err := unix.Open("/", unix.O_RDONLY|unix.O_DIRECTORY|unix.O_CLOEXEC, 0)
	if err != nil {
		return -1, err
	}
	components := strings.Split(strings.TrimPrefix(path, "/"), "/")
	for index, component := range components {
		if component == "" || component == "." || component == ".." {
			unix.Close(fd)
			return -1, ErrMaterial
		}
		next, err := unix.Openat(fd, component, unix.O_RDONLY|unix.O_DIRECTORY|unix.O_CLOEXEC|unix.O_NOFOLLOW, 0)
		unix.Close(fd)
		if err != nil {
			return -1, err
		}
		fd = next
		var stat unix.Stat_t
		if err := unix.Fstat(fd, &stat); err != nil ||
			index < len(components)-1 && !allowUnsafeAncestors && (stat.Uid != 0 || stat.Mode&0o022 != 0) {
			unix.Close(fd)
			return -1, ErrMaterial
		}
	}
	var stat unix.Stat_t
	if err := unix.Fstat(fd, &stat); err != nil || stat.Uid != uid || stat.Gid != gid || stat.Mode&0o777 != mode {
		unix.Close(fd)
		return -1, ErrMaterial
	}
	return fd, nil
}

descriptor.text:
func (fn imdsRoundTrip) RoundTrip(request *http.Request) (*http.Response, error) {
	return fn(request)
}

func ParseDescriptor(data []byte) (Descriptor, error) {
	var descriptor Descriptor
	if len(data) == 0 || len(data) > maxDescriptorBytes ||
		protocol.DecodeStrict(data, &descriptor, maxDescriptorBytes) != nil ||
		descriptor.SchemaVersion != 1 || !descriptorSlotRE.MatchString(descriptor.Slot) {
		return Descriptor{}, ErrInvalidDescriptor
	}
	return descriptor, nil
}

func NewIMDSClient() IMDSClient {
	dialer := &net.Dialer{Timeout: imdsTimeout}
	transport := &http.Transport{
		Proxy: nil, DisableKeepAlives: true, ResponseHeaderTimeout: imdsTimeout,
		DialContext: func(ctx context.Context, network, address string) (net.Conn, error) {
			if network != "tcp" || address != imdsAddress {
				return nil, ErrInvalidDescriptor
			}
			return dialer.DialContext(ctx, network, imdsAddress)
		},
	}
	return IMDSClient{client: &http.Client{
		Timeout: imdsTimeout, Transport: transport,
		CheckRedirect: func(*http.Request, []*http.Request) error { return ErrInvalidDescriptor },
	}}
}

func (imds IMDSClient) FetchDescriptor(ctx context.Context) (Descriptor, error) {
	data, err := imds.fetch(ctx, descriptorEndpoint, maxDescriptorBytes)
	if err != nil {
		return Descriptor{}, err
	}
	return ParseDescriptor(data)
}

func (imds IMDSClient) FetchInstanceID(ctx context.Context) (string, error) {
	data, err := imds.fetch(ctx, identityEndpoint, 255)
	if err != nil {
		return "", err
	}
	id := strings.TrimSpace(string(data))
	if !instanceIDRE.MatchString(id) || !bytes.Equal(bytes.TrimSpace(data), []byte(id)) {
		return "", ErrInvalidDescriptor
	}
	return id, nil
}

func (imds IMDSClient) FetchLaunchMaterial(ctx context.Context) (LaunchMaterial, error) {
	identity, err := imds.fetch(ctx, identityMetadataEndpoint, maxIdentity)
	if errors.Is(err, errMetadataAbsent) {
		return LaunchMaterial{}, ErrNotController
	}
	if err != nil {
		return LaunchMaterial{}, fmt.Errorf("read launch identity metadata: %w", err)
	}
	anchor, err := imds.fetch(ctx, anchorMetadataEndpoint, bootstrap.MaxBootstrapAnchorBytes)
	if err != nil {
		return LaunchMaterial{}, fmt.Errorf("read launch anchor metadata: %w", err)
	}
	enrollment, err := imds.fetch(ctx, hostEnrollmentMetadataEndpoint, hostenroll.MaxPublicBundleBytes)
	if err != nil {
		return LaunchMaterial{}, fmt.Errorf("read launch host enrollment metadata: %w", err)
	}
	operatorSSHKey, err := imds.fetch(ctx, operatorSSHKeyMetadataEndpoint, maxOperatorSSHKey)
	if err != nil {
		return LaunchMaterial{}, fmt.Errorf("read launch operator SSH key metadata: %w", err)
	}
	receipt, err := imds.fetch(ctx, managedHostImageReceiptMetadataEndpoint, trust.MaxEnvelopeBytes)
	if err != nil {
		return LaunchMaterial{}, fmt.Errorf("read launch managed host image receipt: %w", err)
	}
	delegation, err := imds.fetch(ctx, managedHostImageDelegationMetadataEndpoint, trust.MaxEnvelopeBytes)
	if err != nil {
		return LaunchMaterial{}, fmt.Errorf("read launch managed host image delegation: %w", err)
	}
	return LaunchMaterial{Identity: identity, Anchor: anchor, HostEnrollment: enrollment,
		OperatorSSHKey: operatorSSHKey, ManagedHostImageReceipt: receipt, ManagedHostImageDelegation: delegation}, nil
}

func (imds IMDSClient) fetch(ctx context.Context, endpoint string, maximum int64) ([]byte, error) {
	if imds.client == nil || endpoint != descriptorEndpoint && endpoint != identityEndpoint &&
		endpoint != controllerManifestEndpoint && endpoint != identityMetadataEndpoint &&
		endpoint != anchorMetadataEndpoint && endpoint != hostEnrollmentMetadataEndpoint &&
		endpoint != operatorSSHKeyMetadataEndpoint && endpoint != availabilityDomainEndpoint &&
		endpoint != managedHostImageReceiptMetadataEndpoint && endpoint != managedHostImageDelegationMetadataEndpoint &&
		endpoint != faultDomainEndpoint {
		return nil, ErrInvalidDescriptor
	}
	request, err := http.NewRequestWithContext(ctx, http.MethodGet, endpoint, nil)
	if err != nil {
		return nil, err
	}
	request.Header.Set("Authorization", "Bearer Oracle")
	response, err := imds.client.Do(request)
	if err != nil {
		return nil, fmt.Errorf("read fixed OCI IMDS endpoint: %w", err)
	}
	defer response.Body.Close()
	if response.StatusCode == http.StatusNotFound {
		return nil, errMetadataAbsent
	}
	if response.StatusCode != http.StatusOK || response.ContentLength > maximum {
		return nil, ErrInvalidDescriptor
	}
	data, err := io.ReadAll(io.LimitReader(response.Body, maximum+1))
	if err != nil || len(data) == 0 || int64(len(data)) > maximum {
		return nil, ErrInvalidDescriptor
	}
	return data, nil
}

