		}
		slot := fixture.plan.Peers[i].Slot
		fixture.plan.Peers[i].TLSMaterial = bootstrap.FounderTLSMaterialDigests{
			ClientCA: digest([]byte("ca.pem")), ClientCertificate: digest([]byte(slot + "-tls-cert.pem")),
			ClientPrivateKey: digest([]byte(slot + "-tls-key.pem")), RouteCA: digest([]byte("ca.pem")),
			RouteCertificate: digest([]byte(slot + "-tls-cert.pem")), RoutePrivateKey: digest([]byte(slot + "-tls-key.pem")),
		}
	}

	imageWire, grantWire := founderRuntimeImageWires(t, fixture)
	manifests := make(map[string][]byte, 3)
	for slot, wire := range fixture.manifests {
		envelope, err := trust.DecodeEnvelope(wire)
		if err != nil {
			t.Fatal(err)
		}
		var manifest bootstrap.Manifest
		if err := protocol.DecodeStrict(envelope.Payload, &manifest, bootstrap.MaxManifestBytes); err != nil {
			t.Fatal(err)
		}
		if slot == "seed-a" {
			slot = "controller-c"
		}
		manifest.Slot, manifest.SeedSlot, manifest.ControllerSlots = slot, "controller-c", anchor.ControllerSlots
		for i := range manifest.Profiles {
			if manifest.Profiles[i].Slot == "seed-a" {
				manifest.Profiles[i].Slot = "controller-c"
			}
		}
		offline := manifest.Secrets
		manifest.Secrets = acceptedReferences(slot)
		for _, ref := range offline {
			if ref.Purpose == bootstrap.SecretSeedFounder || ref.Purpose == bootstrap.SecretSeedLedgerSigner {
				ref.Slot = slot
				manifest.Secrets = append(manifest.Secrets, ref)
			}
		}
		manifest.ReleaseReceiptSHA256 = digestWire(imageWire)
		manifest.ReleaseImageReceiptWire = imageWire
		manifest.ReleaseDelegationWire = grantWire
		manifest.ControllerFiles = nil
		addTestControllerConfig(&manifest)
		envelope, err = bootstrap.SignManifest(manifest, fixture.now.Add(-time.Minute),
			fixture.now.Add(22*time.Hour), fixture.root)
		if err != nil {
			t.Fatal(err)
		}
		manifests[slot], err = trust.EncodeEnvelope(envelope)
		if err != nil {
			t.Fatal(err)
		}
	}
	fixture.manifests = manifests
	fixture.accepted.ManifestSHA256 = digestWire(fixture.manifests[fixture.accepted.Slot])
	fixture.plan.SeedManifestSHA256 = fixture.accepted.ManifestSHA256
	for index := range fixture.plan.Peers {
		fixture.plan.Peers[index].ManifestSHA256 = digestWire(fixture.manifests[fixture.plan.Peers[index].Slot])
	}
	payload, err := trust.EncodePayload(fixture.plan)
	if err != nil {
		t.Fatal(err)
	}
	planEnvelope, err := trust.Sign(payload, trust.Scope{Domain: bootstrap.FounderPlanDomain,
		DeploymentID: fixture.plan.DeploymentID, Cell: string(fixture.plan.Cell),
		Environment: fixture.plan.Environment, Role: "controller", Slot: fixture.plan.SeedSlot},
		fixture.now.Add(-time.Minute), fixture.now.Add(22*time.Hour), fixture.root)
	if err != nil {
		t.Fatal(err)
	}
	fixture.planWire, err = trust.EncodeEnvelope(planEnvelope)
	if err != nil {
		t.Fatal(err)
	}
	fixture.selection.Generation = 2
	fixture.selection.PlanSHA256 = digestWire(fixture.planWire)
	for index := range fixture.selection.Manifests {
		fixture.selection.Manifests[index].SHA256 = digestWire(fixture.manifests[fixture.selection.Manifests[index].Slot])
	}
	fixture.publish(t, fixture.selection)
	fixture.current, err = fixture.reader(t).ReadCurrent(t.Context(), fixture.now)
	if err != nil {
		t.Fatal(err)
	}
}

signers.text:
func (store FounderSignerStore) Load(current CurrentFounderAuthority, accepted AcceptedInstall,
	roots trust.Keyring, now time.Time,
) (FounderSigningKeys, error) {
	return store.LoadContext(context.Background(), current, accepted, roots, now)
}

func (store FounderSignerStore) LoadContext(ctx context.Context, current CurrentFounderAuthority, accepted AcceptedInstall, roots trust.Keyring, now time.Time) (FounderSigningKeys, error) {
	if accepted.validate() != nil || current.Plan == nil || !current.Plan.IsVerified() || !current.Anchor.IsVerified() ||
		len(roots) == 0 || now.IsZero() || now.Location() != time.UTC ||
		!now.Before(current.SelectionExpiresAt) {
		return FounderSigningKeys{}, ErrFounderSigner
	}
	plan := current.Plan.Plan()
	anchor := current.Anchor.Anchor()
	if plan.SeedSlot != accepted.Slot || plan.SeedManifestSHA256 != accepted.ManifestSHA256 ||
		plan.DeploymentID != accepted.DeploymentID || string(plan.Cell) != accepted.Cell ||
		anchor.ClusterID == "" || plan.AnchorSHA256 != current.Anchor.Digest() {
		return FounderSigningKeys{}, ErrFounderSigner
	}
	seed, err := verifiedFounderManifestContext(ctx, current, accepted.Slot, roots, now)
	if err != nil || seed.Digest() != accepted.ManifestSHA256 {
		return FounderSigningKeys{}, fmt.Errorf("%w: selected accepted seed manifest: %v", ErrFounderSigner, err)
	}
	manifest := seed.Manifest()
	peerReference, err := exactSeedSignerReference(manifest, bootstrap.SecretSeedFounder)
	if err != nil {
		return FounderSigningKeys{}, err
	}
	ledgerReference, err := exactSeedSignerReference(manifest, bootstrap.SecretSeedLedgerSigner)
	if err != nil {
		return FounderSigningKeys{}, err
	}
	if current.Derived != nil {
		return store.loadDerivedKeys(ctx, *current.Derived, accepted, peerReference, ledgerReference, now)
	}
	ledgerGrant, err := current.Anchor.LedgerDelegation()
	if err != nil {
		return FounderSigningKeys{}, fmt.Errorf("%w: selected ledger delegation: %v", ErrFounderSigner, err)
	}
	var peerKeyID string
	for _, row := range plan.Peers {
		peerManifest, err := verifiedFounderManifest(current, row.Slot, roots, now)
		if err != nil || peerManifest.Digest() != row.ManifestSHA256 {
			return FounderSigningKeys{}, fmt.Errorf("%w: selected peer manifest %q: %v", ErrFounderSigner, row.Slot, err)
		}
		peerDelegation := peerManifest.Manifest().PeerReceiptDelegation
		if peerDelegation == nil {
			return FounderSigningKeys{}, ErrFounderSigner
		}
		verified, err := trust.VerifyDelegationCurrent(*peerDelegation, roots, now, bootstrap.ManifestTrustPolicy())
		if err != nil || peerKeyID != "" && peerKeyID != verified.SubjectKeyID() {
			return FounderSigningKeys{}, fmt.Errorf("%w: peer receipt delegations differ or expired: %v", ErrFounderSigner, err)
		}
		peerKeyID = verified.SubjectKeyID()
	}
	if peerKeyID == "" || peerKeyID == ledgerGrant.SubjectKeyID() {
		return FounderSigningKeys{}, fmt.Errorf("%w: receipt and ledger signing roles require distinct delegated keys", ErrFounderSigner)
	}
	fd, err := openMaterialDirectory(store.directory, store.uid, store.gid, 0o700, store.allowUnsafeAncestors)
	if err != nil {
		return FounderSigningKeys{}, fmt.Errorf("%w: open installed seed material: %v", ErrFounderSigner, err)
	}
	defer unix.Close(fd)
	peerKey, err := store.readKey(fd, peerReference, accepted.MaterialSHA256, peerKeyID)
	if err != nil {
		return FounderSigningKeys{}, err
	}
	ledgerKey, err := store.readKey(fd, ledgerReference, accepted.MaterialSHA256, ledgerGrant.SubjectKeyID())
	if err != nil {
		clear(peerKey)
		return FounderSigningKeys{}, err
	}
	return FounderSigningKeys{peer: peerKey, ledger: ledgerKey}, nil
}

func (store FounderSignerStore) readKey(fd int, reference bootstrap.SecretReference,
	installed map[string]string, delegatedKeyID string,
) (ed25519.PrivateKey, error) {
	if installed[reference.TargetFile] != reference.SHA256 {
		return nil, fmt.Errorf("%w: installed material digest differs from seed manifest", ErrFounderSigner)
	}
	wire, err := readMaterial(fd, reference.TargetFile, store.uid, store.gid, reference.SHA256, reference.MaxBytes)
	if err != nil {
		return nil, fmt.Errorf("%w: read exact installed signer: %v", ErrFounderSigner, err)
	}
	defer clear(wire)
	if len(wire) != ed25519.PrivateKeySize ||
		!bytes.Equal(ed25519.NewKeyFromSeed(wire[:ed25519.SeedSize]), wire) {
		return nil, ErrFounderSigner
	}
	key := ed25519.PrivateKey(bytes.Clone(wire))
	keyID, err := trust.KeyID(key.Public().(ed25519.PublicKey))
	if err != nil || keyID != delegatedKeyID {
		clear(key)
		return nil, fmt.Errorf("%w: installed signer key differs from current root delegation", ErrFounderSigner)
	}
	return key, nil
}

func readMaterial(dir int, name string, uid, gid uint32, want string, maximum int64) ([]byte, error) {
	if !markerNameRE.MatchString(name) || !markerDigestRE.MatchString(want) || maximum <= 0 || maximum > bootstrap.MaxSecretBytes {
		return nil, ErrMaterial
	}
	fd, err := unix.Openat(dir, name, unix.O_RDONLY|unix.O_CLOEXEC|unix.O_NOFOLLOW|unix.O_NONBLOCK, 0)
	if err != nil {
		return nil, err
	}
	file := os.NewFile(uintptr(fd), name)
	defer file.Close()
	var stat unix.Stat_t
	if err := unix.Fstat(fd, &stat); err != nil || stat.Mode&unix.S_IFMT != unix.S_IFREG ||
		stat.Uid != uid || stat.Gid != gid || stat.Mode&0o777 != 0o600 || stat.Nlink != 1 ||
		stat.Size <= 0 || stat.Size > maximum {
		return nil, ErrMaterial
	}
	content, err := io.ReadAll(io.LimitReader(file, maximum+1))
	if err != nil || len(content) == 0 || int64(len(content)) > maximum || digest(content) != want {
		clear(content)
		return nil, ErrMaterial
	}
	return content, nil
}

founder_runtime.text:
func (caller founderCaller) checkAntiAffinity(ctx context.Context, plan bootstrap.FounderPlan) error {
	if caller.placement == nil {
		return fmt.Errorf("%w: seed placement source is unavailable", ErrFounderRuntime)
	}
	seed, err := caller.placement(ctx)
	if err != nil {
		return fmt.Errorf("read seed placement: %w", err)
	}
	return bootstrap.CheckControllerAntiAffinity(seed, plan.Peers)
}

func (caller founderCaller) fresh(ctx context.Context, slot string) (founderSnapshot, error) {
	if err := ctx.Err(); err != nil {
		return founderSnapshot{}, err
	}
	selected, err := caller.reader.ReadCurrent(ctx, time.Now().UTC())
	if err != nil {
		return founderSnapshot{}, err
	}
	if selected.Plan.Plan().SeedSlot != caller.accepted.Slot || selected.Anchor.Anchor().ClusterID == "" {
		return founderSnapshot{}, ErrFounderRuntime
	}
	opener := caller.openLedger
	if opener == nil {
		opener = OpenSelectedFounderLedger
	}
	ledger, err := opener(ctx, selected, caller.roots)
	if err != nil {
		return founderSnapshot{}, err
	}
	scope := bootstrap.BootstrapScope{DeploymentID: caller.accepted.DeploymentID, Cell: caller.accepted.Cell, Slot: slot}
	recovery, err := ledger.ReadForManagedPeerRecovery(ctx, scope)
	if errors.Is(err, bootstrap.ErrRecordMissing) {
		return founderSnapshot{selected: selected, ledger: ledger}, errFounderPeerUnreserved
	}
	if err != nil {
		return founderSnapshot{}, err
	}
	now := recovery.AuthorizationTime()
	if now.IsZero() || now.Location() != time.UTC || !now.Before(selected.SelectionExpiresAt) ||
		!now.Before(selected.Anchor.ExpiresAt()) {
		return founderSnapshot{}, ErrFounderRuntime
	}
	snapshot := founderSnapshot{selected: selected, ledger: ledger, recovery: recovery, now: now}
	manifest, err := verifiedFounderManifestContext(ctx, selected, slot, caller.roots, now)
	if err != nil {
		return founderSnapshot{}, err
	}
	if _, err := founderProofIssuedAt(snapshot, selected.ManifestWires[slot], manifest); err != nil {
		return founderSnapshot{}, err
	}
	keys, err := caller.signers.LoadContext(ctx, selected, caller.accepted, caller.roots, now)
	if err != nil {
		return founderSnapshot{}, err
	}
	keys.Close()
	if err := ctx.Err(); err != nil {
		return founderSnapshot{}, err
	}
	now = recovery.AuthorizationTime()
	if now.IsZero() || !now.Before(selected.SelectionExpiresAt) || !now.Before(selected.Anchor.ExpiresAt()) {
		return founderSnapshot{}, ErrFounderRuntime
	}
	peer, err := selected.Plan.AuthorizeFounderPeerRecovery(ctx, slot, recovery, caller.roots, now, selected.SelectionExpiresAt,
		trust.Policy{MaxLifetime: 24 * time.Hour, ClockSkew: bootstrap.ManifestClockSkew})
	if err != nil || !now.Before(peer.EffectDeadline()) {
		return founderSnapshot{}, ErrFounderRuntime
	}
	snapshot.peer, snapshot.now = peer, now
	return snapshot, nil
}

func (caller founderCaller) runPeer(ctx context.Context, slot string) error {
	snapshot, err := caller.fresh(ctx, slot)
	if errors.Is(err, errFounderPeerUnreserved) {
		// Refuse a co-located plan before its row is pinned in the ledger:
		// a reservation pins the plan and peer-row digests, so a corrected,
		// re-signed plan could not recover a slot reserved under this one.
		if err := caller.checkAntiAffinity(ctx, snapshot.selected.Plan.Plan()); err != nil {
			return err
		}
		if err := caller.checkFence(ctx); err != nil {
			return err
		}
		if err := caller.reservePeer(ctx, snapshot, slot); err != nil {
			return fmt.Errorf("reserve planned peer slot: %w", err)
		}
		snapshot, err = caller.fresh(ctx, slot)
	}
	if err != nil {
		return err
	}
	if snapshot.recovery.Phase() == bootstrap.ManagedPeerRecoveryComplete {
		return nil
	}
	var observation FounderOCIObservation
	switch snapshot.recovery.Phase() {
	case bootstrap.ManagedPeerRecoveryClean, bootstrap.ManagedPeerRecoveryManifestOnly:
		if err := caller.checkAntiAffinity(ctx, snapshot.selected.Plan.Plan()); err != nil {
			return err
		}
		attempt, err := NewFounderOCIAttempt(snapshot.peer, snapshot.now)
		if err != nil {
			return err
		}
		instanceID, err := caller.retryLaunch(ctx, attempt, slot)
		recordFounderLaunch(ctx, caller.accepted.Cell, caller.accepted.DeploymentID, slot, attempt, instanceID, err)
		if err != nil {
			return err
		}
		if err := caller.pinCandidate(ctx, snapshot, slot, instanceID); err != nil {
			return fmt.Errorf("pin launched founder candidate: %w", err)
		}
		snapshot, err = caller.fresh(ctx, slot)
		if err != nil {
			return err
		}
		observationAttempt, err := NewFounderOCIObservationAttempt(snapshot.peer, snapshot.now)
		if err != nil || observationAttempt.candidateID != instanceID {
			return fmt.Errorf("%w: launched founder candidate is not the pinned observation target", ErrFounderRuntime)
		}
		observation, err = caller.retryObserve(ctx, observationAttempt, slot, instanceID)
		if err != nil {
			return fmt.Errorf("observe pinned founder candidate: %w", err)
		}
	case bootstrap.ManagedPeerRecoveryCandidateOnly, bootstrap.ManagedPeerRecoveryProofStaged,
		bootstrap.ManagedPeerRecoveryQuarantined, bootstrap.ManagedPeerRecoveryReceiptOnly:
		if snapshot.recovery.Phase() == bootstrap.ManagedPeerRecoveryProofStaged {
			if progress, ok := snapshot.recovery.Progress(); ok &&
				progress.Phase == bootstrap.ManagedPeerProgressResult && snapshot.recovery.State().Result != nil {
				break // Replay the exact staged positive result without another OCI read.
			}
		}
		attempt, err := NewFounderOCIObservationAttempt(snapshot.peer, snapshot.now)
		if err != nil {
			return err
		}
		observation, err = caller.retryObserve(ctx, attempt, slot, attempt.candidateID)
		if err != nil {
			return err
		}
	case bootstrap.ManagedPeerRecoveryResultReady:
		// The exact persisted positive result is sufficient for HEAD repair.
	default:
		return ErrFounderRuntime
	}
	return caller.completePeer(ctx, slot, observation)
}

func (caller founderCaller) reservePeer(ctx context.Context, snapshot founderSnapshot, slot string) error {
	clock := caller.now
	if clock == nil {
		clock = time.Now
	}
	now := clock().UTC().Truncate(time.Second)
	selected := snapshot.selected
	keys, err := caller.signers.LoadContext(ctx, selected, caller.accepted, caller.roots, now)
	if err != nil {
		return err
	}
	defer keys.Close()
	intent, err := selected.Plan.InitialManagedPeerIntent(slot, now)
	if err != nil {
		return err
	}
	expiresAt := earliestFounderTime(selected.Plan.Plan().LaunchDeadline, selected.SelectionExpiresAt,
		selected.Anchor.ExpiresAt())
	if !expiresAt.After(now) {
		return bootstrap.ErrFounderPlanExpired
	}
	intentWire, err := keys.signLedgerRecord(intent, "bootstrap-intent", intent.DeploymentID, intent.Cell,
		intent.Environment, intent.Role, slot, now, expiresAt)
	if err != nil {
		return err
	}
	headWire, err := keys.signHead(bootstrap.SlotHead{SchemaVersion: 1, DeploymentID: intent.DeploymentID,
		Cell: intent.Cell, Environment: intent.Environment, Role: intent.Role, Slot: slot,
		Attempt: intent.Attempt, Generation: intent.Generation, IntentDigest: digest(intentWire)}, now, expiresAt)
	if err != nil {
		return err
	}
	scope := bootstrap.BootstrapScope{DeploymentID: caller.accepted.DeploymentID, Cell: caller.accepted.Cell, Slot: slot}
	_, err = snapshot.ledger.ReserveSlot(ctx, scope, intentWire, headWire)
	return err
}

anti_affinity.text:
func (placement ControllerPlacement) key() (string, bool) {
	ad := strings.ToUpper(strings.TrimSpace(placement.AvailabilityDomain))
	if index := strings.LastIndexByte(ad, ':'); index >= 0 {
		ad = ad[index+1:]
	}
	fd := strings.ToUpper(strings.TrimSpace(placement.FaultDomain))
	return ad + "/" + fd, ad != "" && fd != ""
}

// CheckControllerAntiAffinity requires the seed and every planned peer to be
// in a distinct (availability domain, fault domain) pair. Fault domains are
// scoped to an availability domain, so peers in different ADs may reuse a
// fault-domain name. It is a launch-time check: an already founded slot is
// never relaunched because of it.
func CheckControllerAntiAffinity(seed ControllerPlacement, peers []FounderPeerRow) error {
	key, ok := seed.key()
	if !ok {
		return fmt.Errorf("%w: seed placement is unknown", ErrControllerAntiAffinity)
	}
	owner := map[string]string{key: "seed"}
	for _, peer := range peers {
		key, ok := ControllerPlacement{AvailabilityDomain: peer.AvailabilityDomain, FaultDomain: peer.FaultDomain}.key()
		if !ok {
			return fmt.Errorf("%w: peer %q placement is incomplete", ErrControllerAntiAffinity, peer.Slot)
		}
		if other, exists := owner[key]; exists {
			return fmt.Errorf("%w: peer %q shares %s with %s", ErrControllerAntiAffinity, peer.Slot, key, other)
		}
		owner[key] = fmt.Sprintf("peer %q", peer.Slot)
	}
	return nil
}

completion_fact.text:
func (store *FounderSelectionFloorStore) PeersComplete(accepted AcceptedInstall) bool {
	if accepted.Slot != accepted.SeedSlot {
		return false
	}
	dir, err := store.openDirectory()
	if err != nil {
		return false
	}
	defer unix.Close(dir)
	complete := false
	_ = store.withLock(dir, func() error {
		fd, err := unix.Openat(dir, founderPeersCompleteName, unix.O_RDONLY|unix.O_CLOEXEC|unix.O_NOFOLLOW, 0)
		if err != nil {
			return err
		}
		file := os.NewFile(uintptr(fd), founderPeersCompleteName)
		defer file.Close()
		var stat unix.Stat_t
		if err := unix.Fstat(fd, &stat); err != nil || stat.Mode&unix.S_IFMT != unix.S_IFREG ||
			stat.Mode&0o777 != 0o600 || stat.Uid != store.ownerUID || stat.Nlink != 1 ||
			stat.Size < 1 || stat.Size > founderPeersCompleteMax {
			return ErrFounderSelectionFloor
		}
		wire, err := io.ReadAll(io.LimitReader(file, founderPeersCompleteMax+1))
		if err != nil || len(wire) != int(stat.Size) {
			return ErrFounderSelectionFloor
		}
		var fact founderPeersCompleteFact
		if protocol.DecodeStrict(wire, &fact, founderPeersCompleteMax) != nil {
			return ErrFounderSelectionFloor
		}
		canonical, err := protocol.EncodeJSON(fact)
		if err != nil || !bytes.Equal(canonical, wire) {
			return ErrFounderSelectionFloor
		}
		complete = fact == newFounderPeersCompleteFact(accepted)
		return nil
	})
	return complete
}

func (store *FounderSelectionFloorStore) MarkPeersComplete(accepted AcceptedInstall) error {
	if accepted.validate() != nil || accepted.Slot != accepted.SeedSlot {
		return ErrFounderRuntime
	}
	wire, err := protocol.EncodeJSON(newFounderPeersCompleteFact(accepted))
	if err != nil || len(wire) > founderPeersCompleteMax {
		return ErrFounderSelectionFloor
	}
	dir, err := store.openDirectory()
	if err != nil {
		return err
	}
	defer unix.Close(dir)
	return store.withLock(dir, func() error {
		var nonce [12]byte
		if _, err := rand.Read(nonce[:]); err != nil {
			return err
		}
		temporary := ".founder-peers-complete." + hex.EncodeToString(nonce[:])
		fd, err := unix.Openat(dir, temporary,
			unix.O_WRONLY|unix.O_CREAT|unix.O_EXCL|unix.O_CLOEXEC|unix.O_NOFOLLOW, 0o600)
		if err != nil {
			return err
		}
		remove := true
		defer func() {
			if remove {
				_ = unix.Unlinkat(dir, temporary, 0)
			}
		}()
		file := os.NewFile(uintptr(fd), temporary)
		written, writeErr := file.Write(wire)
		if written != len(wire) && writeErr == nil {
			writeErr = io.ErrShortWrite
		}
		syncErr := file.Sync()
		closeErr := file.Close()
		if err := errors.Join(writeErr, syncErr, closeErr); err != nil {
			return err
		}
		if err := unix.Renameat(dir, temporary, dir, founderPeersCompleteName); err != nil {
			return err
		}
		remove = false
		return unix.Fsync(dir)
	})
}

floor_artifact.text:
func BuildVerifiedPeerFloorArtifacts(ctx context.Context, baked BakedInputs, accepted AcceptedInstall,
	state bootstrap.SlotState, objects FounderSelectionObjectReader,
	serviceUID, serviceGID uint32, now time.Time,
) ([]FounderFloorArtifact, error) {
	if serviceUID == 0 || serviceGID == 0 || accepted.Slot == accepted.SeedSlot {
		return nil, ErrFounderPeerContinuation
	}
	reader, err := NewCurrentFounderAuthorityReader(baked, accepted, objects, new(FounderSelectionFloorStore))
	if err != nil {
		return nil, err
	}
	started := time.Now()
	selected, err := reader.readCurrentPeerInitial(ctx, now)
	if err != nil {
		return nil, err
	}
	checker := FounderPeerContinuation{reader: reader}
	if err := checker.checkBindings(accepted, state, selected, now); err != nil {
		return nil, err
	}
	if err := reader.confirmCurrentPeerSelection(ctx, selected,
		func() time.Time { return now.Add(time.Since(started)) }); err != nil {
		return nil, err
	}
	return founderFloorArtifacts(selected.SelectionGeneration, selected.SelectionSHA256, serviceUID, serviceGID)
}

func BuildVerifiedSeedFloorArtifacts(ctx context.Context, baked BakedInputs, accepted AcceptedInstall,
	state bootstrap.SlotState, objects FounderSelectionObjectReader,
	serviceUID, serviceGID uint32, now time.Time,
) ([]FounderFloorArtifact, error) {
	if serviceUID == 0 || serviceGID == 0 || accepted.validate() != nil ||
		accepted.Slot != accepted.SeedSlot || accepted.HeadAttempt != 1 || accepted.HeadGeneration != 1 ||
		state.Intent.Mode != bootstrap.IntentModeExternalSeed || state.Head.ResultDigest != accepted.ResultSHA256 ||
		state.ResultRecord == nil || state.ResultRecord.SHA256 != accepted.ResultSHA256 ||
		state.ManifestRecord == nil || state.ManifestRecord.SHA256 != accepted.ManifestSHA256 {
		return nil, ErrFounderProvision
	}
	reader, err := NewCurrentFounderAuthorityReader(baked, accepted, objects, new(FounderSelectionFloorStore))
	if err != nil {
		return nil, err
	}
	selected, err := reader.readCurrent(ctx, now, false)
	if err != nil || selected.SelectionGeneration != 1 || selected.Anchor.Digest() != accepted.AnchorSHA256 ||
		selected.Plan.Plan().SeedManifestSHA256 != accepted.ManifestSHA256 {
		return nil, ErrFounderProvision
	}
	if err := reader.confirmCurrentSelection(ctx, selected, now); err != nil {
		return nil, err
	}
	return founderFloorArtifacts(selected.SelectionGeneration, selected.SelectionSHA256, serviceUID, serviceGID)
}

func founderFloorArtifacts(generation uint64, selectorDigest string, serviceUID, serviceGID uint32) ([]FounderFloorArtifact, error) {
	wire, err := encodeFounderSelectionFloor(generation, selectorDigest)
	if err != nil || serviceUID == 0 || serviceGID == 0 {
		return nil, ErrFounderSelectionFloor
	}
	return []FounderFloorArtifact{
		{Path: FounderSelectionFloorDirectory, Mode: 0o700, UID: serviceUID, GID: serviceGID, Directory: true},
		{Path: filepath.Join(FounderSelectionFloorDirectory, founderSelectionLockName),
			Mode: 0o600, UID: serviceUID, GID: serviceGID},
		{Path: filepath.Join(FounderSelectionFloorDirectory, founderSelectionFloorName),
			Bytes: wire, Mode: 0o600, UID: serviceUID, GID: serviceGID},
	}, nil
}

func (checker *FounderPeerContinuation) Initialize(ctx context.Context, marker AcceptedInstall,
	state bootstrap.SlotState, now time.Time,
) error {
	if checker == nil || checker.reader == nil || checker.floor == nil ||
		checker.serviceUID == 0 || checker.serviceGID == 0 || checker.now == nil ||
		now.IsZero() || now.Location() != time.UTC {
		return ErrFounderPeerContinuation
	}
	started := time.Now()
	selected, err := checker.reader.readCurrentPeerInitial(ctx, now)
	if err != nil {
		return fmt.Errorf("%w: read current selected founder proof: %v", ErrFounderPeerContinuation, err)
	}
	if err := checker.checkBindings(marker, state, selected, now); err != nil {
		return err
	}
	if err := prepareFounderFloorOwner(checker.floor, checker.serviceUID, checker.serviceGID); err != nil {
		return fmt.Errorf("%w: prepare peer selection floor: %v", ErrFounderPeerContinuation, err)
	}
	if err := checker.floor.InitializePeerForService(selected.SelectionGeneration, selected.SelectionSHA256,
		checker.serviceGID); err != nil {
		return fmt.Errorf("%w: publish peer selection floor: %v", ErrFounderPeerContinuation, err)
	}
	if err := checker.reader.confirmCurrentPeerSelection(ctx, selected,
		func() time.Time { return checker.now().Round(0).UTC().Add(time.Since(started)) }); err != nil {
		return fmt.Errorf("%w: selector changed after floor publication: %v", ErrFounderPeerContinuation, err)
	}
	return nil
}

