func (f *controllerRecipientFixture) serveHTTP(w http.ResponseWriter, r *http.Request) {
	if r.Header.Get("Authorization") == "" {
		http.Error(w, "unsigned SDK request", 401)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	if strings.HasPrefix(r.URL.Path, "/n/namespace-a/b/") {
		f.objectReads++
		bucket, key, ok := strings.Cut(strings.TrimPrefix(r.URL.Path, "/n/namespace-a/b/"), "/o/")
		if !ok {
			http.Error(w, "invalid object path", 400)
			return
		}
		if r.Method == http.MethodPut {
			// Observe each write at OCI's whole-second timestamp precision.
			f.objects.now = time.Now().UTC().Truncate(time.Second)
			response, err := f.objects.PutObject(r.Context(), objectstorage.PutObjectRequest{
				NamespaceName: new("namespace-a"), BucketName: new(bucket), ObjectName: new(key),
				OpcSseKmsKeyId: new(r.Header.Get("opc-sse-kms-key-id")), OpcContentSha256: new(r.Header.Get("opc-content-sha256")),
				ContentLength: new(r.ContentLength), PutObjectBody: r.Body,
				IfMatch: recipientOptionalHeader(r, "if-match"), IfNoneMatch: recipientOptionalHeader(r, "if-none-match")})
			if err != nil {
				http.Error(w, `{"code":"PreconditionFailed","message":"conditional write rejected"}`, 412)
				return
			}
			w.Header().Set("ETag", value(response.ETag))
			return
		}
		if r.Method != http.MethodGet {
			http.Error(w, "GET or conditional PUT required", 405)
			return
		}
		stored, exists := f.objects.objects[bucket+"/"+key]
		if !exists {
			wire, ok := f.founder.objects.items[bucket+"/"+key]
			if !ok {
				http.Error(w, `{"code":"ObjectNotFound","message":"absent"}`, 404)
				return
			}
			stored = founderStoredObject{wire: wire, etag: digestWire(wire), modified: f.founder.now}
		}
		w.Header().Set("ETag", stored.etag)
		w.Header().Set("Last-Modified", stored.modified.Format(http.TimeFormat))
		w.Header().Set("Date", time.Now().UTC().Format(http.TimeFormat))
		w.Header().Set("Content-Length", fmt.Sprint(len(stored.wire)))
		_, _ = w.Write(stored.wire)
		return
	}
	f.sdkReads++
	var body any
	if strings.HasPrefix(r.URL.Path, "/20160918/instances/") {
		observed, ok := f.live[strings.TrimPrefix(r.URL.Path, "/20160918/instances/")]
		if !ok {
			http.Error(w, "unknown instance", 404)
			return
		}
		body = core.Instance{Id: new(observed.InstanceOCID), CompartmentId: new(observed.CompartmentOCID),
			ImageId: new(observed.ImageOCID), AvailabilityDomain: new(observed.AvailabilityDomain),
			FaultDomain: new(observed.FaultDomain), Shape: new(observed.Shape), LifecycleState: core.InstanceLifecycleStateEnum(observed.LifecycleState)}
		if f.afterInstance != nil {
			callback := f.afterInstance
			f.afterInstance = nil
			callback()
		}
	} else if r.URL.Path == "/20160918/vnicAttachments" {
		observed, ok := f.live[r.URL.Query().Get("instanceId")]
		if !ok {
			http.Error(w, "unknown attachment instance", 404)
			return
		}
		body = []core.VnicAttachment{{InstanceId: new(observed.InstanceOCID), CompartmentId: new(observed.CompartmentOCID),
			VnicId: new(observed.PrimaryVNICOCID), SubnetId: new(observed.SubnetOCID), LifecycleState: core.VnicAttachmentLifecycleStateAttached}}
	} else {
		for _, observed := range f.live {
			switch r.URL.Path {
			case "/20160918/vnics/" + observed.PrimaryVNICOCID:
				body = core.Vnic{Id: new(observed.PrimaryVNICOCID), CompartmentId: new("ocid1.compartment.oc1..network"),
					AvailabilityDomain: new(observed.AvailabilityDomain), SubnetId: new(observed.SubnetOCID),
					PrivateIp: new(observed.PrimaryPrivateIP), IsPrimary: new(observed.PrimaryVNIC), NsgIds: observed.NSGOCIDs,
					LifecycleState: core.VnicLifecycleStateAvailable}
			case "/20160918/subnets/" + observed.SubnetOCID:
				body = core.Subnet{Id: new(observed.SubnetOCID), CompartmentId: new("ocid1.compartment.oc1..network"),
					VcnId: new("ocid1.vcn.oc1.sa-saopaulo-1.recipient"), LifecycleState: core.SubnetLifecycleStateAvailable}
			}
		}
	}
	if body == nil {
		http.Error(w, "unexpected OCI SDK operation", 404)
		return
	}
	if err := json.MarshalWrite(w, body); err != nil {
		http.Error(w, err.Error(), 500)
	}
}

func readControllerHostRecipient(ctx context.Context, reader *CurrentFounderAuthorityReader, issuer AcceptedIdentity,
	signedSpec []byte, node, instanceID, privateIP string, sources controllerRecipientSources,
) (*ControllerHostRecipient, error) {
	started := time.Now()
	proof := &ControllerHostRecipient{reader: reader, sources: sources, issuer: issuer.Clone(), spec: bytes.Clone(signedSpec),
		node: node, instanceID: instanceID, privateIP: privateIP, started: started,
		validUntil: started.Add(bootstrap.ManagedPeerObservationMaxAge)}
	grant, authority, err := proof.current(ctx)
	if err != nil {
		return nil, err
	}
	proof.slot, proof.region = grant.Controller, authority.identity.OCIRegion
	if authority.expires.Before(proof.validUntil) {
		proof.validUntil = authority.expires
	}
	if !proof.Valid(time.Now()) {
		return nil, bootstrap.ErrManagedPeerObservationStale
	}
	return proof, nil
}

func (proof *ControllerHostRecipient) current(ctx context.Context) (cellspec.HostGrant, RuntimeAuthority, error) {
	fail := func(err error) (cellspec.HostGrant, RuntimeAuthority, error) {
		return cellspec.HostGrant{}, RuntimeAuthority{}, err
	}
	if proof == nil || proof.reader == nil || proof.issuer.Validate() != nil || proof.node == "" ||
		!instanceIDRE.MatchString(proof.instanceID) || !validPrivateIPv4(proof.privateIP) ||
		len(proof.spec) == 0 || len(proof.spec) > cellspec.MaxSignedBytes || proof.started.IsZero() ||
		!time.Now().Before(proof.validUntil) || !time.Now().Before(proof.started.Add(bootstrap.ManagedPeerObservationMaxAge)) {
		return fail(ErrAdmission)
	}
	ctx, stop := context.WithDeadline(ctx, proof.started.Add(bootstrap.ManagedPeerObservationMaxAge))
	defer stop()
	inputs, err := proof.sources.trust.loadTrustInputs(proof.issuer)
	if err != nil {
		return fail(err)
	}
	// The fixed adopted chain supplies both current grants and historical
	// launch verification; a caller-provided keyring cannot select authority.
	reader := *proof.reader
	reader.baked = proof.reader.baked
	reader.baked.Roots = inputs.Roots.Historical
	authority, err := reader.ReadRuntimeAuthority(ctx, proof.issuer, time.Now().UTC())
	if err != nil {
		return fail(err)
	}
	identity := authority.identity
	signed, err := cellspec.VerifyHistorical(proof.spec, inputs.Roots.Current, cellspec.Identity{
		DeploymentID: identity.DeploymentID, Cell: strings.ToLower(identity.Cell), Environment: identity.Environment})
	if err != nil || !signed.RootSigned {
		return fail(errors.New("controller recipient requires a root-signed host grant under current roots"))
	}
	grant, ok := signed.Grant(proof.node)
	if !ok || grant.Controller == "" || grant.Node != proof.node || grant.Environment != identity.Environment ||
		grant.PrivateIP != proof.privateIP || len(grant.Roles) == 0 || slices.Contains(grant.Roles, "function-worker") ||
		slices.Contains(grant.Roles, "terrabase") || !slices.Contains(authority.plan.ControllerSlots, grant.Controller) ||
		proof.slot != "" && proof.slot != grant.Controller || proof.region != "" && proof.region != identity.OCIRegion {
		return fail(errors.New("controller recipient differs from its signed host grant"))
	}
	if authority.anchor.ExpiresAt().Before(authority.expires) {
		authority.expires = authority.anchor.ExpiresAt()
	}
	ctx, cancel := context.WithDeadline(ctx, authority.expires)
	defer cancel()
	var ledger SlotReader
	if proof.sources.ledger != nil {
		ledger = proof.sources.ledger
	} else if reader.derived != nil {
		ledger, err = reader.derived.OpenLedger(ctx, reader.baked.Roots)
	} else {
		config, configErr := currentLedgerConfig(authority.anchor, reader.baked.Roots)
		if configErr != nil {
			return fail(configErr)
		}
		ledger, err = openInstancePrincipalLedger(ctx, config, nil)
	}
	if err != nil {
		return fail(err)
	}
	scope := bootstrap.BootstrapScope{DeploymentID: identity.DeploymentID, Cell: identity.Cell, Slot: grant.Controller}
	state, err := readSlot(ctx, ledger, scope)
	if err != nil {
		return fail(err)
	}
	if err := proof.checkCompletedSlot(authority, grant, state); err != nil {
		return fail(err)
	}
	observer := proof.sources.observer
	if observer == nil {
		observer, err = reader.RuntimeInstanceObserver(ctx, proof.issuer)
		if err != nil {
			return fail(err)
		}
	}
	observed, err := (Gate{Instances: observer}).observe(ctx, proof.instanceID, state, authority.anchor.Anchor())
	if err != nil {
		return fail(err)
	}
	if observed.PrimaryPrivateIP != grant.PrivateIP || grant.Controller == proof.issuer.Slot &&
		(observed.InstanceOCID != proof.issuer.InstanceOCID || observed.ImageOCID != proof.issuer.ImageOCID ||
			observed.PrimaryVNICOCID != proof.issuer.PrimaryVNICOCID || observed.PrimaryPrivateIP != proof.issuer.PrimaryPrivateIP) {
		return fail(errors.New("controller recipient differs from its live primary address or accepted local identity"))
	}
	startup, err := controllerRecipientStartup(ctx, authority, reader.baked.Roots, grant.Controller, state.Intent.ImageOCID)
	if err != nil {
		return fail(err)
	}
	if startup.ExpiresAt().Before(authority.expires) {
		authority.expires = startup.ExpiresAt()
	}
	expectedReceipt, err := bootstrap.NewReceipt(startup, observed.Facts)
	if err != nil {
		return fail(err)
	}
	receipt := state.PeerReceipt
	if grant.Controller == authority.plan.SeedSlot {
		receipt = state.SeedReceipt
	}
	if receipt == nil || *receipt != expectedReceipt {
		return fail(errors.New("controller recipient differs from its protected historical receipt and live OCI facts"))
	}
	confirmed, err := readSlot(ctx, ledger, scope)
	if err != nil {
		return fail(err)
	}
	if !sameControllerRecipientSlot(state, confirmed) {
		return fail(errors.New("controller slot changed during live recipient verification"))
	}
	current, err := reader.ReadRuntimeAuthority(ctx, proof.issuer, time.Now().UTC())
	if err != nil || current.identity != identity || current.selectionDigest != authority.selectionDigest ||
		current.planDigest != authority.planDigest || !time.Now().Before(authority.expires) {
		return fail(errors.New("controller issuer authority changed during live recipient verification"))
	}
	freshRoots, err := proof.sources.trust.loadTrustInputs(proof.issuer)
	if err != nil || freshRoots.Roots.Head != inputs.Roots.Head || freshRoots.Roots.Sequence != inputs.Roots.Sequence {
		return fail(errors.New("adopted roots changed during controller recipient verification"))
	}
	if !time.Now().Before(authority.expires) || !time.Now().Before(proof.validUntil) ||
		!time.Now().Before(proof.started.Add(bootstrap.ManagedPeerObservationMaxAge)) {
		return fail(bootstrap.ErrManagedPeerObservationStale)
	}
	if proof.slot != "" && authority.expires.Before(proof.validUntil) {
		return fail(errors.New("controller recipient authority shortened; reconstruct its proof"))
	}
	if err := ctx.Err(); err != nil {
		return fail(err)
	}
	return grant, authority, nil
}

func (observer *OCIInstanceObserver) ObserveInstance(ctx context.Context, candidateID string) (InstanceObservation, error) {
	if observer == nil || observer.compute == nil || observer.network == nil ||
		!instanceIDRE.MatchString(candidateID) {
		return InstanceObservation{}, ErrInstanceObservation
	}
	response, err := observer.compute.GetInstance(observationContext(ctx, observer.compute), core.GetInstanceRequest{InstanceId: new(candidateID)})
	if err != nil {
		return InstanceObservation{}, fmt.Errorf("GetInstance exact IMDS candidate: %w", err)
	}
	instance := response.Instance
	if value(instance.Id) != candidateID || !strings.HasPrefix(value(instance.CompartmentId), "ocid1.compartment.") ||
		!strings.HasPrefix(value(instance.ImageId), "ocid1.image.") || value(instance.AvailabilityDomain) == "" ||
		value(instance.FaultDomain) == "" || value(instance.Shape) == "" {
		return InstanceObservation{}, ErrInstanceObservation
	}
	observation := InstanceObservation{
		InstanceOCID: candidateID, CompartmentOCID: value(instance.CompartmentId),
		ImageOCID: value(instance.ImageId), ETag: value(response.Etag),
		AvailabilityDomain: value(instance.AvailabilityDomain), FaultDomain: value(instance.FaultDomain),
		Shape: value(instance.Shape), LifecycleState: string(instance.LifecycleState),
	}
	if instance.FreeformTags != nil {
		observation.BootstrapCreateKey = instance.FreeformTags["BootstrapCreateKey"]
	}
	var page *string
	seenPages := make(map[string]struct{})
	count := 0
	for {
		attachments, err := observer.compute.ListVnicAttachments(observationContext(ctx, observer.compute), core.ListVnicAttachmentsRequest{
			CompartmentId: new(observation.CompartmentOCID), InstanceId: new(candidateID),
			Limit: new(50), Page: page,
		})
		if err != nil {
			return InstanceObservation{}, fmt.Errorf("ListVnicAttachments exact instance: %w", err)
		}
		count += len(attachments.Items)
		if count > maxObservedVNICAttachments || len(attachments.Items) == 0 && attachments.OpcNextPage != nil {
			return InstanceObservation{}, ErrInstanceObservation
		}
		for _, attachment := range attachments.Items {
			if value(attachment.InstanceId) != candidateID ||
				value(attachment.CompartmentId) != observation.CompartmentOCID {
				return InstanceObservation{}, ErrInstanceObservation
			}
			if attachment.LifecycleState != core.VnicAttachmentLifecycleStateAttached {
				continue
			}
			vnicID := value(attachment.VnicId)
			if !strings.HasPrefix(vnicID, "ocid1.vnic.") {
				return InstanceObservation{}, ErrInstanceObservation
			}
			vnicResponse, err := observer.network.GetVnic(observationContext(ctx, observer.network), core.GetVnicRequest{VnicId: new(vnicID)})
			if err != nil {
				return InstanceObservation{}, fmt.Errorf("GetVnic attached to exact instance: %w", err)
			}
			vnic := vnicResponse.Vnic
			if value(vnic.Id) != vnicID ||
				value(vnic.AvailabilityDomain) != observation.AvailabilityDomain ||
				vnic.LifecycleState != core.VnicLifecycleStateAvailable ||
				value(vnic.SubnetId) != value(attachment.SubnetId) {
				return InstanceObservation{}, ErrInstanceObservation
			}
			subnetResponse, err := observer.network.GetSubnet(observationContext(ctx, observer.network), core.GetSubnetRequest{SubnetId: vnic.SubnetId})
			if err != nil {
				return InstanceObservation{}, fmt.Errorf("GetSubnet attached VNIC: %w", err)
			}
			if !vnicSubnetMatches(vnic, subnetResponse.Subnet, candidateID) {
				return InstanceObservation{}, ErrInstanceObservation
			}
			if vnic.IsPrimary == nil || !*vnic.IsPrimary {
				continue
			}
			if observation.PrimaryVNIC {
				return InstanceObservation{}, fmt.Errorf("%w: multiple attached primary VNICs", ErrInstanceObservation)
			}
			observation.PrimaryVNIC = true
			observation.PrimaryVNICOCID = vnicID
			observation.PrimaryPrivateIP = value(vnic.PrivateIp)
			observation.SubnetOCID = value(vnic.SubnetId)
			observation.NSGOCIDs = append([]string(nil), vnic.NsgIds...)
		}
		if attachments.OpcNextPage == nil || *attachments.OpcNextPage == "" {
			break
		}
		if _, exists := seenPages[*attachments.OpcNextPage]; exists {
			return InstanceObservation{}, ErrInstanceObservation
		}
		seenPages[*attachments.OpcNextPage] = struct{}{}
		page = attachments.OpcNextPage
	}
	if !observation.PrimaryVNIC || !validPrivateIPv4(observation.PrimaryPrivateIP) {
		return InstanceObservation{}, ErrInstanceObservation
	}
	return observation, nil
}

func (f *controllerRecipientFixture) completeSeed(t *testing.T) {
	t.Helper()
	founder, ledger := f.founder, f.sources.ledger
	now := time.Now().UTC().Truncate(time.Second)
	slot := founder.plan.SeedSlot
	envelope, err := trust.DecodeEnvelope(founder.manifests[slot])
	if err != nil {
		t.Fatal(err)
	}
	expected, err := founder.current.Anchor.ManifestExpectation(slot, founder.plan.Peers[0].ImageOCID)
	if err != nil {
		t.Fatal(err)
	}
	manifest, err := bootstrap.VerifyManifest(envelope, founder.baked.Roots, expected, now, bootstrap.ManifestTrustPolicy())
	if err != nil {
		t.Fatal(err)
	}
	profile, ok := manifest.Profile(slot)
	if !ok {
		t.Fatal("seed has no signed profile")
	}
	reservation, err := BuildExternalSeedReservation(ExternalSeedReservationRequest{
		Identity: founder.baked.Identity, Anchor: founder.current.Anchor, Manifest: manifest,
		ReviewedPlanSHA256: digestWire(founder.planWire), CreateIdentity: "recipient-seed-create",
		LedgerPrivate: founder.ledgerKey, Now: now, ExpiresAt: now.Add(time.Hour)})
	if err != nil {
		t.Fatal(err)
	}
