		NSGOCIDs: slices.Clone(profile.NetworkSecurityGroupOCIDs), PrimaryVNICOCID: "ocid1.vnic.oc1.sa-saopaulo-1." + slot,
		PrimaryPrivateIP: founder.plan.SeedPrivateIP, PrimaryVNIC: true, LifecycleState: "RUNNING"}
