func recipientRegistration(proof *ControllerHostRecipient) host.Registration {
	return host.Registration{ID: entityid.Derive("host", "gru", proof.Node()), Node: proof.Node(), Cell: "gru",
		Environment: proof.Environment(), Roles: []string{"ts-auth"}, Generation: 1}
}

func (proof *ControllerHostRecipient) Valid(now time.Time) bool {
	return proof != nil && proof.slot != "" && proof.region != "" && !now.IsZero() &&
		!proof.started.IsZero() && !now.Before(proof.started) && now.Before(proof.validUntil) &&
		time.Now().Before(proof.validUntil) && time.Now().Before(proof.started.Add(bootstrap.ManagedPeerObservationMaxAge))
}

func (proof *ControllerHostRecipient) Verify(ctx context.Context) error {
	if !proof.Valid(time.Now()) {
		return ErrAdmission
	}
	_, _, err := proof.current(ctx)
	if err == nil && !proof.Valid(time.Now()) {
		return bootstrap.ErrManagedPeerObservationStale
	}
	return err
}

func (proof *ControllerHostRecipient) VerifyRegistration(ctx context.Context, registration host.Registration) error {
	if !proof.Valid(time.Now()) {
		return ErrAdmission
	}
	grant, authority, err := proof.current(ctx)
	if err != nil {
		return err
	}
	if registration.ID != entityid.Derive("host", strings.ToLower(authority.identity.Cell), proof.node) ||
		registration.Node != proof.node || registration.Cell != strings.ToLower(authority.identity.Cell) ||
		registration.Environment != proof.issuer.Environment || registration.Generation == 0 ||
		!slices.Equal(registration.Roles, grant.Roles) || registration.ManagedOCI != nil ||
		registration.ManagedMember != nil || registration.ManagedPlacement != nil {
		return errors.New("controller registration differs from its signed slot and host grant")
	}
	if !proof.Valid(time.Now()) {
		return bootstrap.ErrManagedPeerObservationStale
	}
	return nil
}

func (proof *ControllerHostRecipient) checkCompletedSlot(authority RuntimeAuthority, grant cellspec.HostGrant, state bootstrap.SlotState) error {
	identity := authority.identity
	if state.ManifestRecord == nil || state.Result == nil || state.ResultRecord == nil ||
		state.Head.ResultDigest != state.ResultRecord.SHA256 || state.Result.InstanceOCID != proof.instanceID ||
		state.Intent.DeploymentID != identity.DeploymentID || state.Intent.Cell != identity.Cell ||
		state.Intent.Environment != identity.Environment || state.Intent.Slot != grant.Controller ||
		state.Head.Attempt != state.Intent.Attempt || state.Head.Generation != state.Intent.Generation ||
		state.Result.Attempt != state.Head.Attempt || state.Intent.ManifestDigest != state.ManifestRecord.SHA256 ||
		state.ManifestRecord.SHA256 != digestWire(authority.manifests[grant.Controller]) {
		return errors.New("controller recipient has no exact currently selected completed slot")
	}
	if grant.Controller == authority.plan.SeedSlot {
		if state.Intent.Mode != bootstrap.IntentModeExternalSeed || state.Result.Mode != bootstrap.IntentModeExternalSeed ||
			state.SeedReceipt == nil || state.SeedReceiptRecord == nil || state.Result.SeedReceiptDigest != state.SeedReceiptRecord.SHA256 ||
			grant.PrivateIP != authority.plan.SeedPrivateIP {
			return ErrAdmission
		}
		return nil
	}
	if state.Intent.Mode != bootstrap.IntentModeManaged || state.Result.Mode != bootstrap.IntentModeManaged ||
		state.Candidate == nil || state.CandidateRecord == nil || state.PeerReceipt == nil || state.PeerReceiptRecord == nil ||
		state.Head.CandidateDigest != state.CandidateRecord.SHA256 || state.Candidate.InstanceOCID != proof.instanceID ||
		state.Candidate.IntentDigest != state.IntentRecord.SHA256 || state.Result.PeerReceiptDigest != state.PeerReceiptRecord.SHA256 ||
		state.Intent.FounderPlanSHA256 != authority.planDigest ||
		state.ResultRecord.LastModified.IsZero() || state.HeadRecord.LastModified.IsZero() ||
		state.ResultRecord.LastModified.Add(time.Second).After(authority.plan.LaunchDeadline) ||
		state.HeadRecord.LastModified.Add(time.Second).After(authority.plan.LaunchDeadline) {
		return errors.New("controller peer lacks its exact protected candidate, result and receipt")
	}
	for _, row := range authority.plan.Peers {
		if row.Slot != grant.Controller {
			continue
		}
		rowDigest, err := bootstrap.FounderPeerRowDigest(row)
		if err == nil && rowDigest == state.Intent.PeerRowDigest && state.Candidate.FounderPlanSHA256 == authority.planDigest &&
			state.Candidate.PeerRowDigest == rowDigest && row.PrivateIP == grant.PrivateIP && row.ImageOCID == state.Intent.ImageOCID &&
			row.ManifestSHA256 == state.ManifestRecord.SHA256 && row.CompartmentOCID == state.Intent.CompartmentOCID {
			return nil
		}
	}
	return ErrAdmission
}

func (reader *CurrentFounderAuthorityReader) ReadRuntimeAuthority(ctx context.Context,
	accepted AcceptedIdentity, now time.Time,
) (RuntimeAuthority, error) {
	if reader == nil || accepted.Validate() != nil {
		return RuntimeAuthority{}, errors.New("runtime requires an accepted controller identity")
	}
	marker := reader.accepted
	if marker.DeploymentID != accepted.DeploymentID || marker.Cell != accepted.Cell ||
		marker.Slot != accepted.Slot || marker.SeedSlot != accepted.SeedSlot ||
		marker.InstanceOCID != accepted.InstanceOCID || marker.ImageOCID != accepted.ImageOCID ||
		marker.PrimaryVNICOCID != accepted.PrimaryVNICOCID || marker.PrimaryPrivateIP != accepted.PrimaryPrivateIP {
		return RuntimeAuthority{}, errors.New("runtime identity differs from accepted founder installation")
	}
	var plan bootstrap.FounderPlan
	var anchor bootstrap.VerifiedBootstrapAnchor
	var expires time.Time
	var manifests map[string][]byte
	var planDigest, selectionDigest string
	var derived *bootstrap.DerivedFounderPlan
	if marker.Slot == marker.SeedSlot {
		selected, err := reader.ReadCurrent(ctx, now)
		if err != nil {
			return RuntimeAuthority{}, err
		}
		plan, anchor, expires, manifests = selected.Plan.Plan(), selected.Anchor, selected.SelectionExpiresAt, selected.ManifestWires
		planDigest, selectionDigest, derived = selected.Plan.Digest(), selected.SelectionSHA256, selected.Derived
	} else {
		selected, err := reader.readCurrentCompletedPeer(ctx, now, true)
		if err != nil {
			return RuntimeAuthority{}, err
		}
		if selected.derived != nil {
			plan = selected.derived.Plan()
		} else {
			// Legacy continuation retains the exact verified root-signed wire.
			envelope, err := trust.DecodeEnvelope(selected.PlanWire)
			if err != nil || protocol.DecodeStrict(envelope.Payload, &plan, bootstrap.MaxFounderPlanBytes) != nil {
				return RuntimeAuthority{}, ErrFounderSelection
			}
		}
		anchor, expires, manifests = selected.Anchor, selected.SelectionExpiresAt, selected.ManifestWires
		planDigest, selectionDigest, derived = selected.Plan.Digest(), selected.SelectionSHA256, selected.derived
	}
	if !anchor.IsVerified() || anchor.Digest() != marker.AnchorSHA256 ||
		anchor.Anchor().ClusterID != accepted.ClusterID || anchor.Anchor().Environment != accepted.Environment ||
		plan.SeedSlot != accepted.SeedSlot || digestWire(manifests[accepted.Slot]) != marker.ManifestSHA256 ||
		!now.Before(expires) {
		return RuntimeAuthority{}, errors.New("runtime scope differs from current signed controller authority")
	}
	privateIP := plan.SeedPrivateIP
	if accepted.Slot != plan.SeedSlot {
		privateIP = ""
		for _, row := range plan.Peers {
			if row.Slot == accepted.Slot && row.ImageOCID == accepted.ImageOCID {
				privateIP = row.PrivateIP
			}
		}
	}
	if privateIP == "" || privateIP != accepted.PrimaryPrivateIP {
		return RuntimeAuthority{}, errors.New("runtime host address differs from signed slot and accepted instance")
	}
	return RuntimeAuthority{identity: RuntimeIdentity{
		DeploymentID: accepted.DeploymentID, ClusterID: accepted.ClusterID,
		Environment: accepted.Environment, Cell: accepted.Cell,
		OCIRegion: anchor.Anchor().OCIRegion,
		Slot:      accepted.Slot, SeedSlot: accepted.SeedSlot, InstanceID: accepted.InstanceOCID,
		PrivateIP: privateIP, SeedPrivateIP: plan.SeedPrivateIP,

func (store bakedStore) loadTrustInputs(accepted AcceptedIdentity) (TrustInputs, error) {
	if err := accepted.Validate(); err != nil {
		return TrustInputs{}, err
	}
	genesis, err := store.loadRoots()
	if err != nil {
		return TrustInputs{}, err
	}
	chain, err := readAcceptedRootChain(store.chainFile)
	if err != nil {
		return TrustInputs{}, err
	}
	identity := trust.ChainIdentity{DeploymentID: accepted.DeploymentID, Environment: accepted.Environment,
		Cell: strings.ToLower(accepted.Cell)}
	roots, err := trust.VerifyRootChain(genesis, identity, chain)
	if err != nil {
		return TrustInputs{}, fmt.Errorf("verify accepted deployment root lineage: %w", err)
	}
	return TrustInputs{ChainIdentity: identity, Genesis: genesis, Chain: chain, Roots: roots}, nil
}

