func BuildExternalSeedReservation(request ExternalSeedReservationRequest) (ExternalSeedReservationRecords, error) {
	if request.Manifest == nil {
		return ExternalSeedReservationRecords{}, ErrExternalSeedRecord
	}
	anchor := request.Anchor.Anchor()
	manifest := request.Manifest.Manifest()
	if !request.Anchor.IsVerified() || request.Manifest.Digest() == "" ||
		request.Identity.DeploymentID != anchor.DeploymentID || request.Identity.Cell != anchor.Cell ||
		request.Identity.Environment != anchor.Environment || manifest.SeedSlot != manifest.Slot ||
		manifest.DeploymentID != anchor.DeploymentID || manifest.Cell != anchor.Cell ||
		manifest.Environment != anchor.Environment || manifest.OCIRegion != anchor.OCIRegion ||
		!slices.Contains(anchor.ControllerSlots, manifest.SeedSlot) ||
		!externalSeedDigestRE.MatchString(request.ReviewedPlanSHA256) ||
		!externalSeedCreateRE.MatchString(request.CreateIdentity) ||
		manifest.SeedSlot == "" || !request.ExpiresAt.After(request.Now) ||
		len(request.LedgerPrivate) != ed25519.PrivateKeySize {
		return ExternalSeedReservationRecords{}, ErrExternalSeedRecord
	}
	if err := verifyExternalLedgerKey(request.Manifest, request.Anchor, request.LedgerPrivate); err != nil {
		return ExternalSeedReservationRecords{}, err
	}
	profile, ok := request.Manifest.Profile(manifest.SeedSlot)
	if !ok {
		return ExternalSeedReservationRecords{}, ErrExternalSeedRecord
	}
	profileWire, err := trust.EncodePayload(profile)
	if err != nil {
		return ExternalSeedReservationRecords{}, err
	}
	intent := bootstrap.Intent{SchemaVersion: 1, Mode: bootstrap.IntentModeExternalSeed,
		DeploymentID: anchor.DeploymentID, Cell: string(anchor.Cell), Environment: anchor.Environment,
		Role: "controller", Slot: manifest.SeedSlot, Attempt: 1, Generation: 1,
		ManifestDigest: request.Manifest.Digest(), ReleaseReceiptDigest: manifest.ReleaseReceiptSHA256,
		RegionIntentGeneration: anchor.InitialRegionIntentGeneration, ImageOCID: manifest.ImageOCID,
		RegionIntentDigest: anchor.InitialRegionIntentSHA256, LaunchRequestDigest: externalSeedDigest(profileWire),
		ReviewedPlanDigest: request.ReviewedPlanSHA256, CreateKey: request.CreateIdentity,
		CreatedAt: request.Now, OCIRegion: anchor.OCIRegion, CompartmentOCID: profile.CompartmentOCID,
		AvailabilityDomain: profile.AvailabilityDomain, FaultDomain: profile.FaultDomain,
		SubnetOCID: profile.SubnetOCID, NetworkSecurityGroupIDs: slices.Clone(profile.NetworkSecurityGroupOCIDs),
		Shape: profile.Shape, Node: manifest.SeedSlot}
	intentWire, err := signExternalSeedRecord(intent, "bootstrap-intent", manifest.SeedSlot, request.Identity,
		request.LedgerPrivate, request.Anchor, request.Manifest, request.Now, request.ExpiresAt)
	if err != nil {
		return ExternalSeedReservationRecords{}, err
	}
	head := bootstrap.SlotHead{SchemaVersion: 1, DeploymentID: anchor.DeploymentID,
		Cell: string(anchor.Cell), Environment: anchor.Environment, Role: "controller",
		Slot: manifest.SeedSlot, Attempt: 1, Generation: 1, IntentDigest: externalSeedDigest(intentWire)}
	headWire, err := signExternalSeedRecord(head, "bootstrap-slot-head", manifest.SeedSlot, request.Identity,
		request.LedgerPrivate, request.Anchor, request.Manifest, request.Now, request.ExpiresAt)
	if err != nil {
		return ExternalSeedReservationRecords{}, err
	}
	return ExternalSeedReservationRecords{IntentWire: intentWire, InitialHeadWire: headWire}, nil
}

func BuildExternalSeedCompletion(request ExternalSeedCompletionRequest) (ExternalSeedCompletionRecords, error) {
	if request.Manifest == nil {
		return ExternalSeedCompletionRecords{}, ErrExternalSeedRecord
	}
	anchor := request.Anchor.Anchor()
	if !request.Anchor.IsVerified() || request.Manifest.Digest() == "" ||
		request.Identity.DeploymentID != anchor.DeploymentID || request.Identity.Cell != anchor.Cell ||
		request.Identity.Environment != anchor.Environment || !request.ExpiresAt.After(request.Now) ||
		request.ObservedAt.IsZero() || request.ObservedAt.Location() != time.UTC ||
		request.ObservedAt.After(request.Now.Add(bootstrap.ManifestClockSkew)) ||
		request.Now.Sub(request.ObservedAt) > bootstrap.ExternalSeedObservationMaxAge ||
		len(request.LedgerPrivate) != ed25519.PrivateKeySize {
		return ExternalSeedCompletionRecords{}, ErrExternalSeedRecord
	}
	if err := verifyExternalLedgerKey(request.Manifest, request.Anchor, request.LedgerPrivate); err != nil {
		return ExternalSeedCompletionRecords{}, err
	}
	facts, err := VerifyExternalSeedObservation(request.Anchor, request.Manifest, request.State,
		request.Observation, request.ExpectedPrivateIP)
	if err != nil {
		return ExternalSeedCompletionRecords{}, err
	}
	receiptWire := slices.Clone(request.ReuseReceiptWire)
	if len(receiptWire) == 0 {
		var envelope trust.Envelope
		var signErr error
		if derived, ok := request.Manifest.(bootstrap.DerivedStartupAuthority); ok {
			envelope, signErr = bootstrap.SignDerivedReceipt(derived, facts, request.Now, request.ExpiresAt, request.LedgerPrivate)
		} else if legacy, ok := request.Manifest.(bootstrap.VerifiedManifest); ok {
			envelope, signErr = bootstrap.SignSeedReceipt(legacy, facts, request.Now, request.ExpiresAt, request.RootPrivate)
		} else {
			return ExternalSeedCompletionRecords{}, ErrExternalSeedRecord
		}
		if signErr != nil {
			return ExternalSeedCompletionRecords{}, signErr
		}
		receiptWire, err = trust.EncodeEnvelope(envelope)
		if err != nil {
			return ExternalSeedCompletionRecords{}, err
		}
	}
	receiptEnvelope, err := trust.DecodeEnvelope(receiptWire)
	if err != nil {
		return ExternalSeedCompletionRecords{}, err
	}
	if _, err := bootstrap.VerifySeedReceipt(receiptEnvelope, request.Manifest, request.Roots,
		facts, request.Now, bootstrap.ManifestTrustPolicy()); err != nil {
		return ExternalSeedCompletionRecords{}, err
	}
	resultExpiresAt := request.ExpiresAt
	if receiptEnvelope.ExpiresAt.Before(resultExpiresAt) {
		resultExpiresAt = receiptEnvelope.ExpiresAt
	}
	profileWire, err := trust.EncodePayload(facts.Profile)
	if err != nil {
		return ExternalSeedCompletionRecords{}, err
	}
	intent := request.State.Intent
	result := bootstrap.Result{SchemaVersion: 1, Mode: bootstrap.IntentModeExternalSeed,
		DeploymentID: intent.DeploymentID, Cell: intent.Cell, Environment: intent.Environment,
		Role: "controller", Slot: intent.Slot, Attempt: intent.Attempt, Generation: intent.Generation,
		RegionIntentGeneration: intent.RegionIntentGeneration,
		IntentDigest:           request.State.IntentRecord.SHA256, InstanceOCID: request.Observation.InstanceOCID,
		ETag: request.Observation.ETag, OCIRegion: intent.OCIRegion,
		CompartmentOCID: request.Observation.CompartmentOCID, ImageOCID: request.Observation.ImageOCID,
		Shape: request.Observation.Shape, ObservedProfileDigest: externalSeedDigest(profileWire),
		SeedReceiptDigest: externalSeedDigest(receiptWire), CreateKey: intent.CreateKey,
		ObservedAt: request.ObservedAt}
	resultWire, err := signExternalSeedRecord(result, "bootstrap-result", intent.Slot, request.Identity,
		request.LedgerPrivate, request.Anchor, request.Manifest, request.Now, resultExpiresAt)
	if err != nil {
		return ExternalSeedCompletionRecords{}, err
	}
	head := request.State.Head
	head.ResultDigest = externalSeedDigest(resultWire)
	headWire, err := signExternalSeedRecord(head, "bootstrap-slot-head", intent.Slot, request.Identity,
		request.LedgerPrivate, request.Anchor, request.Manifest, request.Now, resultExpiresAt)
	if err != nil {
		return ExternalSeedCompletionRecords{}, err
	}
	return ExternalSeedCompletionRecords{ReceiptWire: receiptWire, ResultWire: resultWire,
		CompletedHeadWire: headWire}, nil
}

func (ledger *Ledger) ReserveSlot(ctx context.Context, scope BootstrapScope, intentBytes, initialHeadBytes []byte) (SlotState, error) {
	if err := validateLedgerScope(scope); err != nil {
		return SlotState{}, err
	}
	if err := ledger.validateAnchorScope(scope); err != nil {
		return SlotState{}, err
	}
	intent, intentEnvelope, intentErr := ledger.decodeIntent(scope, intentBytes, true)
	if intentErr != nil {
		return SlotState{}, intentErr
	}
	if intent.Attempt != 1 || intent.Generation != 1 {
		return SlotState{}, fmt.Errorf("%w: an initial reservation must begin at attempt and generation one", ErrInvalidRecord)
	}
	head, headErr := ledger.decodeHead(scope, initialHeadBytes, true)
	headAuthorizedNow := headErr == nil
	if headErr != nil {
		return SlotState{}, headErr
	}
	if head.Attempt != intent.Attempt || head.Generation != intent.Generation || head.IntentDigest != objectDigest(intentBytes) ||
		head.ResultDigest != "" || head.CandidateDigest != "" || head.PreviousAttempt != 0 || head.RetirementDigest != "" {
		return SlotState{}, ErrSlotNotReserved
	}
	intentRecord, err := ledger.createOrRead(ctx, scope, intent.Attempt, ledgerIntent, intentBytes)
	if err != nil {
		return SlotState{}, err
	}
	clockErr := validIntentClock(intent, intentRecord, ledger.config.TrustPolicy.ClockSkew)
	if clockErr != nil {
		return SlotState{}, clockErr
	}
	if err := validateStoredInterval(intentRecord, intentEnvelope); err != nil {
		return SlotState{}, err
	}
	if err := ledger.validateStoredBeforeAnchorExpiry(intentRecord); err != nil {
		return SlotState{}, err
	}
	// Intent creation and HEAD admission are separate Object Storage calls. The
	// intent may expire while the HEAD write is in flight, so verify current
	// authority again immediately before admitting the initial HEAD.
	currentIntent, currentIntentRecord, err := ledger.refreshCurrentIntent(ctx, scope, intent, intentBytes)
	if err != nil {
		return SlotState{}, err
	}
	if !sameIntent(currentIntent, intent) || currentIntentRecord.SHA256 != intentRecord.SHA256 {
		return SlotState{}, ErrRecordAuthorization
	}
	intentRecord = currentIntentRecord
	if err := ledger.validateCurrentAuthority(ctx); err != nil {
		return SlotState{}, err
	}
	_, headRecord, err := ledger.writeInitialHead(ctx, scope, head, initialHeadBytes, headAuthorizedNow)
	if err != nil {
		return SlotState{}, err
	}
	if err := validateStoredBeforeExpiry(headRecord, intentEnvelope.ExpiresAt); err != nil {
		return SlotState{}, err
	}
	if err := validateHeadWithinRetryWindow(headRecord, intentRecord); err != nil {
		return SlotState{}, err
	}
	if err := ledger.validateStoredBeforeAnchorExpiry(headRecord); err != nil {
		return SlotState{}, err
	}
	return ledger.ReadSlot(ctx, scope)
}

func (ledger *Ledger) ReadSlot(ctx context.Context, scope BootstrapScope) (SlotState, error) {
	state, err := ledger.readSlot(ctx, scope, false)
	if err == nil {
		return state, nil
	}
	// Managed peer records can be valid historical evidence whose
	// signed interval or exact proof timing is no longer current. Preserve that
	// distinction for read-only callers while keeping malformed or mismatched
	// records as hard errors.
	quarantined, recoveryErr := ledger.readSlotWithRecovery(ctx, scope, false, true)
	if recoveryErr == nil && quarantined.Intent.Mode == IntentModeManaged &&
		quarantined.quarantined {
		return SlotState{}, fmt.Errorf("%w: slot %q", ErrManagedPeerProofQuarantined, scope.Slot)
	}
	return SlotState{}, err
}

func (ledger *Ledger) RecordExternalSeed(
	ctx context.Context,
	scope BootstrapScope,
	manifestBytes []byte,
	receiptBytes []byte,
	facts InstanceFacts,
	resultBytes []byte,
	headWithResultBytes []byte,
) (SlotState, error) {
	state, err := ledger.readSlot(ctx, scope, false)
	if err != nil {
		return SlotState{}, err
	}
	if state.Intent.Mode != IntentModeExternalSeed {
		return SlotState{}, ErrExternalSeedMode
	}
	if state.Head.ResultDigest != "" {
		if state.HeadRecord.SHA256 == objectDigest(headWithResultBytes) &&
			state.Head.ResultDigest == objectDigest(resultBytes) && state.ResultRecord != nil &&
			state.ResultRecord.SHA256 == objectDigest(resultBytes) && state.ManifestRecord != nil &&
			state.ManifestRecord.SHA256 == objectDigest(manifestBytes) && state.SeedReceiptRecord != nil &&
			state.SeedReceiptRecord.SHA256 == objectDigest(receiptBytes) {
			return state, nil
		}
		return SlotState{}, ErrSlotHeadConflict
	}
	result, err := ledger.decodeResult(scope, resultBytes, false)
	if err != nil {
		return SlotState{}, err
	}
	if result.Mode != IntentModeExternalSeed || result.Attempt != state.Head.Attempt || result.Generation != state.Head.Generation ||
		result.IntentDigest != state.IntentRecord.SHA256 || result.SeedReceiptDigest != objectDigest(receiptBytes) || result.PeerReceiptDigest != "" {
		return SlotState{}, ErrSlotHeadConflict
	}
	if err := validateResultForIntent(result, state.Intent, state.IntentRecord.SHA256); err != nil {
		return SlotState{}, err
	}
	if err := validateManagedFacts(ledger, facts, state.Intent, state.IntentRecord.SHA256, result); err != nil {
		return SlotState{}, err
	}
	manifestRecord, manifestExists, err := ledger.readExistingExact(ctx, scope, state.Head.Attempt, ledgerManifest, manifestBytes)
	if err != nil {
		return SlotState{}, err
	}
	receiptRecord, receiptExists, err := ledger.readExistingExact(ctx, scope, state.Head.Attempt, ledgerSeedReceipt, receiptBytes)
	if err != nil {
		return SlotState{}, err
	}
	resultRecord, resultExists, err := ledger.readExistingExact(ctx, scope, result.Attempt, ledgerResult, resultBytes)
	if err != nil {
		return SlotState{}, err
	}
	if resultExists && (!manifestExists || !receiptExists) {
		return SlotState{}, fmt.Errorf("%w: an existing result cannot authorize creating a missing manifest or receipt", ErrRecordAuthorization)
	}
	if objectDigest(manifestBytes) != state.Intent.ManifestDigest {
		return SlotState{}, ErrSlotHeadConflict
	}
	updatedHead, headErr := ledger.decodeHead(scope, headWithResultBytes, true)
	if headErr != nil {
		return SlotState{}, headErr
	}
	expectedHead := state.Head
	expectedHead.ResultDigest = objectDigest(resultBytes)
	if !sameHead(updatedHead, expectedHead) {
		return SlotState{}, ErrSlotHeadConflict
	}

	verifiedManifest, manifestEnvelope, manifestErr := ledger.verifyCurrentIntentManifest(ctx, scope, state.Intent, manifestBytes)
	manifestCurrent := manifestErr == nil
	var historicalManifest HistoricalStartupAuthority
	if manifestErr != nil {
		if !manifestExists {
			return SlotState{}, manifestErr
		}
		historicalManifest, manifestEnvelope, err = ledger.verifyHistoricalIntentManifest(ctx, scope, state.Intent, manifestBytes)
		if err != nil {
			return SlotState{}, err
		}
	}
	receiptEnvelope, err := trust.DecodeEnvelope(receiptBytes)
	if err != nil {
		return SlotState{}, fmt.Errorf("%w: decode canonical seed receipt envelope: %v", ErrInvalidRecord, err)
	}
	var receipt Receipt
	receiptCurrent := false
	var receiptCurrentErr error
	if manifestCurrent {
		verifiedReceipt, verifyErr := VerifySeedReceipt(receiptEnvelope, verifiedManifest, ledger.config.TrustRoots, facts, ledger.now(), ledger.config.TrustPolicy)
		if verifyErr == nil {
			receipt = verifiedReceipt.Receipt()
			receiptCurrent = true
		} else {
			receiptCurrentErr = verifyErr
			if !receiptExists {
				return SlotState{}, verifyErr
			}
		}
	}
	if !resultExists && (!manifestCurrent || !receiptCurrent) {
		if manifestErr != nil {
			return SlotState{}, manifestErr
		}
		if receiptCurrentErr != nil {
			return SlotState{}, receiptCurrentErr
		}
		return SlotState{}, ErrRecordAuthorization
	}
	if !receiptCurrent {
		if !manifestExists || !receiptExists {
			if manifestErr != nil {
				return SlotState{}, manifestErr
			}
			return SlotState{}, ErrRecordAuthorization
		}
		historicalManifest, _, err = ledger.verifyHistoricalIntentManifest(ctx, scope, state.Intent, manifestBytes)
		if err != nil {
			return SlotState{}, err
		}
		historicalReceipt, verifyErr := VerifyHistoricalSeedReceipt(receiptEnvelope, historicalManifest, ledger.config.TrustRoots, facts, ledger.config.TrustPolicy)
		if verifyErr != nil {
			return SlotState{}, verifyErr
		}
		receipt = historicalReceipt.Receipt()
	}
	if err := validateSeedReceiptForIntent(receipt, state.Intent, state.IntentRecord.SHA256); err != nil {
		return SlotState{}, err
	}
	if err := validateSeedReceiptForResult(receipt, result); err != nil {
		return SlotState{}, err
	}
	if _, err := ledger.decodeResult(scope, resultBytes, true); err != nil && !resultExists {
		return SlotState{}, err
	}
	if !manifestExists {
		manifestRecord, err = ledger.createOrRead(ctx, scope, state.Head.Attempt, ledgerManifest, manifestBytes)
		if err != nil {
			return SlotState{}, err
		}
	}
	if err := validateStoredInterval(manifestRecord, manifestEnvelope); err != nil {
		return SlotState{}, err
	}
	if err := ledger.validateStoredBeforeAnchorExpiry(manifestRecord); err != nil {
		return SlotState{}, err
	}
	if !receiptExists {
		receiptRecord, err = ledger.createOrRead(ctx, scope, state.Head.Attempt, ledgerSeedReceipt, receiptBytes)
		if err != nil {
			return SlotState{}, err
		}
	}
	if err := validateStoredInterval(receiptRecord, receiptEnvelope); err != nil {
		return SlotState{}, err
	}
	if err := ledger.validateStoredBeforeAnchorExpiry(receiptRecord); err != nil {
		return SlotState{}, err
	}
	if !resultExists {
		currentManifest, _, verifyErr := ledger.verifyCurrentIntentManifest(ctx, scope, state.Intent, manifestBytes)
		if verifyErr != nil {
			return SlotState{}, verifyErr
		}
		currentReceipt, verifyErr := VerifySeedReceipt(
			receiptEnvelope, currentManifest, ledger.config.TrustRoots, facts, ledger.now(), ledger.config.TrustPolicy,
		)
		if verifyErr != nil {
			return SlotState{}, fmt.Errorf("%w: root-signed seed receipt expired before the result write: %v", ErrRecordAuthorization, verifyErr)
		}
		receipt = currentReceipt.Receipt()
		if err := validateSeedReceiptForIntent(receipt, state.Intent, state.IntentRecord.SHA256); err != nil {
			return SlotState{}, err
		}
		if err := validateSeedReceiptForResult(receipt, result); err != nil {
			return SlotState{}, err
		}
		resultRecord, err = ledger.createOrRead(ctx, scope, result.Attempt, ledgerResult, resultBytes)
		if err != nil {
			return SlotState{}, err
		}
	}
	if err := validateResultClock(result, resultRecord, ledger.config.TrustPolicy.ClockSkew); err != nil {
		return SlotState{}, err
	}
	resultEnvelope, err := trust.DecodeEnvelope(resultBytes)
	if err != nil {
		return SlotState{}, fmt.Errorf("%w: decode result envelope: %v", ErrInvalidRecord, err)
	}
	if err := validateStoredInterval(resultRecord, resultEnvelope); err != nil {
		return SlotState{}, err
	}
	if err := validateResultStoredWithinProofs(manifestRecord, receiptRecord, resultRecord, ledger.config.AnchorExpiresAt); err != nil {
		return SlotState{}, err
	}
	if err := validateCompletionWriteOrder(manifestRecord, receiptRecord, resultRecord); err != nil {
		return SlotState{}, err
	}
	if _, _, err := ledger.writeHead(ctx, scope, state.HeadRecord.ETag, updatedHead, headWithResultBytes, true); err != nil {
		return SlotState{}, err
	}
	return ledger.ReadSlot(ctx, scope)
}

func (ledger *Ledger) readObjectLimit(ctx context.Context, bucket, objectName string, maximum int) (StoredRecord, error) {
	if ledger.config.DerivedStartup != nil {
		authority := *ledger.config.DerivedStartup
		if ledger.now().Before(authority.ExpiresAt()) {
			if err := authority.VerifyCurrent(ctx, ledger.now()); err != nil {
				return StoredRecord{}, err
			}
		} else if _, err := authority.historical(ctx, authority.Wire()); err != nil {
			return StoredRecord{}, err
		}
	}
	response, err := ledger.client.GetObject(ociclient.RequestContext(ctx), objectstorage.GetObjectRequest{
		NamespaceName: new(ledger.config.Namespace),
		BucketName:    new(bucket),
		ObjectName:    new(objectName),
	})
	if err != nil {
		if serviceErr, ok := errors.AsType[objectStorageServiceError](err); ok && serviceErr.GetHTTPStatusCode() == http.StatusNotFound {
			return StoredRecord{}, ErrRecordMissing
		}
		return StoredRecord{}, fmt.Errorf("read exact bootstrap object: %w", err)
	}
	if response.Content == nil {
		return StoredRecord{}, errors.New("bootstrap object response has no body")
	}
	if response.ContentLength == nil || *response.ContentLength < 1 || *response.ContentLength > int64(maximum) {
		response.Content.Close()
		return StoredRecord{}, errors.New("bootstrap object has missing or invalid content length")
	}
	body, err := io.ReadAll(io.LimitReader(response.Content, int64(maximum)+1))
	closeErr := response.Content.Close()
	if err := errors.Join(err, closeErr); err != nil {
		return StoredRecord{}, fmt.Errorf("read bootstrap object body: %w", err)
	}
	if len(body) != int(*response.ContentLength) || len(body) > maximum {
		return StoredRecord{}, errors.New("bootstrap object body length does not match its metadata")
	}
	if response.ETag == nil || strings.TrimSpace(*response.ETag) == "" || response.LastModified == nil {
		return StoredRecord{}, errors.New("bootstrap object is missing ETag or Last-Modified metadata")
	}
	if response.RawResponse == nil {
		return StoredRecord{}, errors.New("bootstrap object response is missing server headers")
	}
	serverDate, err := http.ParseTime(response.RawResponse.Header.Get("Date"))
	if err != nil {
		return StoredRecord{}, errors.New("bootstrap object response has a missing or invalid server Date")
	}
	lastModified := response.LastModified.Time.UTC()
	serverDate = serverDate.UTC()
	if lastModified.IsZero() || serverDate.Before(lastModified) {
		return StoredRecord{}, errors.New("bootstrap object server timestamps are inconsistent")
	}
	digest := sha256.Sum256(body)
	return StoredRecord{
		Bytes: body, SHA256: hex.EncodeToString(digest[:]), ETag: *response.ETag,
		LastModified: lastModified, ServerDate: serverDate,
	}, nil
}

func (store *founderLedgerObjects) PutObject(_ context.Context, request objectstorage.PutObjectRequest) (objectstorage.PutObjectResponse, error) {
	if request.NamespaceName == nil || request.BucketName == nil || request.ObjectName == nil ||
		request.OpcSseKmsKeyId == nil || request.PutObjectBody == nil {
		return objectstorage.PutObjectResponse{}, errors.New("incomplete founder ledger write")
	}
	wire, err := io.ReadAll(request.PutObjectBody)
	if err != nil {
		return objectstorage.PutObjectResponse{}, err
	}
	_ = request.PutObjectBody.Close()
	if request.ContentLength == nil || *request.ContentLength != int64(len(wire)) ||
		request.OpcContentSha256 == nil || *request.OpcContentSha256 != base64Digest(wire) {
		return objectstorage.PutObjectResponse{}, errors.New("founder ledger write changed content")
	}
	if store.rejectSuffix != "" && strings.HasSuffix(*request.ObjectName, store.rejectSuffix) ||
		store.rejectPart != "" && strings.Contains(*request.ObjectName, store.rejectPart) {
		return objectstorage.PutObjectResponse{}, errors.New("injected founder ledger write failure")
	}
	key := *request.BucketName + "/" + *request.ObjectName
	previous, exists := store.objects[key]
	if request.IfNoneMatch != nil && *request.IfNoneMatch == "*" && exists ||
		request.IfMatch != nil && (!exists || previous.etag != *request.IfMatch) {
		return objectstorage.PutObjectResponse{}, founderStorageError(http.StatusPreconditionFailed)
	}
	if request.IfNoneMatch == nil && request.IfMatch == nil {
		return objectstorage.PutObjectResponse{}, errors.New("unconditional founder ledger write")
	}
	hash := sha256.Sum256(wire)
	etag := `"` + hex.EncodeToString(hash[:8]) + `"`
	store.objects[key] = founderStoredObject{wire: bytes.Clone(wire), etag: etag, modified: store.now}
	store.writes++
	return objectstorage.PutObjectResponse{ETag: new(etag)}, nil
}

func (store *founderLedgerObjects) GetObject(_ context.Context, request objectstorage.GetObjectRequest) (objectstorage.GetObjectResponse, error) {
	if request.NamespaceName == nil || request.BucketName == nil || request.ObjectName == nil {
		return objectstorage.GetObjectResponse{}, errors.New("incomplete founder ledger read")
	}
	object, ok := store.objects[*request.BucketName+"/"+*request.ObjectName]
	if !ok {
		return objectstorage.GetObjectResponse{}, founderStorageError(http.StatusNotFound)
	}
	headers := make(http.Header)
	headers.Set("Date", store.now.Format(http.TimeFormat))
	length := int64(len(object.wire))
	modified := common.SDKTime{Time: object.modified}
	if store.afterGet != nil {
		store.afterGet(*request.ObjectName)
	}
	return objectstorage.GetObjectResponse{RawResponse: &http.Response{Header: headers},
		Content: io.NopCloser(bytes.NewReader(object.wire)), ContentLength: &length,
		ETag: new(object.etag), LastModified: &modified}, nil
}

